uniform float amzp_satMax;
uniform float amzp_satSoftness;
uniform float amzp_lumMin;
uniform float amzp_lumMax;
uniform float amzp_lumSoftness;
uniform float amzp_keyDenoise;
uniform float amzp_keyExpand;
uniform float amzp_keyBlur;
