        float key = hueMask * satMask * lumMask;
        if (amzp_keyDenoise > 0.00001) {
            float threshold = amzp_keyDenoise;
            key = smoothstep(threshold, threshold + 0.1, key);
        }
        if (abs(amzp_keyExpand) > 0.00001) {
            if (amzp_keyExpand > 0.0) {
                key = smoothstep(0.0, 1.0 - amzp_keyExpand, key);
            } else {
