        if ((amzp_keyInvert>0.5)) {
            key = 1.0 - key;
        }
        return clamp(key, 0.0, 1.0);
    }
    float3 gradeInside(float3 rgb, float3 hsl) {
        float3 graded = hsl;
        float hueShift = amzp_gradeHueShift / 360.0;
        if (amzp_gradeHueRotate > 0.00001) {
            hueShift += time * amzp_gradeHueRotate;
        }
        graded.x = fract(graded.x + hueShift);
        graded.y = clamp(graded.y + amzp_gradeSaturation, 0.0, 1.0);
        if (abs(amzp_gradeVibrance) > 0.00001) {
            float currentSat = graded.y;
            float vibranceMod = 1.0 - clamp(currentSat * 2.0, 0.0, 1.0);
            graded.y = clamp(graded.y + amzp_gradeVibrance * vibranceMod, 0.0, 1.0);
        }
        graded.z = clamp(graded.z + amzp_gradeLuminance * 0.5, 0.0, 1.0);
        if (abs(amzp_gradeContrast) > 0.00001) {
            float c = 1.0 + amzp_gradeContrast;
            graded.z = clamp((graded.z - 0.5) * c + 0.5, 0.0, 1.0);
        }
        if (abs(amzp_gradeGamma - 1.0) > 0.00001) {
            graded.z = pow(max(graded.z, 0.0), 1.0 / max(amzp_gradeGamma, 0.00001));
        }
        float3 result = hsl2rgb(graded);
        if (amzp_gradeTintStrength > 0.00001) {
            result = mix(result, result * amzp_gradeTint.rgb, amzp_gradeTintStrength);
        }
        if (abs(amzp_gradeTemperature) > 0.00001) {
            result.r += amzp_gradeTemperature * 0.06;
