        bool outsideActive = (abs(amzp_outsideSaturation) > 0.00001 ||
                              abs(amzp_outsideLuminance) > 0.00001 ||
                              abs(amzp_outsideContrast) > 0.00001);
        if (!outsideActive) {
            result = mix(rgb, insideGraded, key);
        }
        result = mix(rgb, result, amzp_globalMix);
        result = clamp(result, 0.0, 1.0);
        amzOutput = float4(result, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
